// AUTOGENERATED. DO NOT MODIFY.
// To modify this file, run: node scripts/m3/gen-keyboard-tests.mjs slider
// Spec: m3.material.io 2026-10-13_06-10-19, sliders "Keyboard navigation"
//
// Each case presses real keys and checks the behavior the spec's keyboard
// table lists for that key. `xit` cases are known differences from the spec.

// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-slider.js';
import {type SliderElement} from './slider-element.js';

interface SetupOptions {
  /** Index of the item to render selected. */
  selected?: number;
  /** Value step (sliders). */
  step?: number;
}

interface Fixture {
  root: HTMLElement;
  items: HTMLElement[];
  before: HTMLElement;
  after: HTMLElement;
  /** Indices of the items that received a click (activation). */
  activated: number[];
  // Menus.
  invoker?: HTMLElement;
  menu?: HTMLElement;
  submenu?: HTMLElement;
  submenuItems?: HTMLElement[];
}

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

function fixture(root: HTMLElement, items: HTMLElement[]): Fixture {
  const activated: number[] = [];
  items.forEach((item, i) => {
    item.addEventListener('click', (event) => {
      // Clicks bubbling from nested items (submenus) are not this item's.
      const path = event.composedPath();
      if (path.find((el) => items.includes(el as HTMLElement)) === item) {
        activated.push(i);
      }
    });
  });
  return {
    root,
    items,
    activated,
    before: root.querySelector<HTMLElement>('#before')!,
    after: root.querySelector<HTMLElement>('#after')!,
  };
}

/** Waits for Lit updates, a frame and pending timeouts. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  // Twice: popover toggle events, and the timeouts they start, can land
  // after the next frame.
  for (let i = 0; i < 2; i++) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
    await new Promise((resolve) => setTimeout(resolve));
  }
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** Holds keys down while pressing another. */
async function hold(held: string[], key: string) {
  for (const k of held) await sendKeys({down: k});
  await sendKeys({press: key});
  for (const k of [...held].reverse()) await sendKeys({up: k});
  await settle();
}

/** The focused element and the focused elements of its shadow roots. */
function focusPath() {
  const path: Element[] = [];
  let el = document.activeElement;
  while (el) {
    path.push(el);
    el = el.shadowRoot?.activeElement ?? null;
  }
  return path;
}

/** The index of the item that holds focus, or -1. */
function focusedIndex(items: Element[]) {
  const path = focusPath();
  return items.findIndex((item) =>
    path.some((el) => el === item || item.contains(el)),
  );
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: Fixture, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}

async function setup(opts: SetupOptions = {}): Promise<Fixture> {
  const root = await mount(html`
    <button id="before">Before</button>
    <md-gb-slider
      aria-label="Volume"
      min="0"
      max="100"
      value="50"
      step=${opts.step ?? 1}
      ?ticks=${opts.step !== undefined}></md-gb-slider>
    <button id="after">After</button>
  `);
  return fixture(root, [...root.querySelectorAll<HTMLElement>('md-gb-slider')]);
}

function valueOf(f: Fixture) {
  return (f.items[0] as SliderElement).value;
}

describe('<md-gb-slider> keyboard (spec)', () => {
  afterEach(() => {
    container?.remove();
    container = undefined;
  });

  // Spec: "Tab" | "Moves focus to the slider handle"
  // spec: sliders-ec5f07, sliders-da649b
  describe("Tab: Moves focus to the slider handle", () => {
    it("Tab moves focus to the first item", async () => {
      const f = await setup();
      f.before.focus();
      await press('Tab');
      expect(focusedIndex(f.items)).toBe(0);
    });
  });

  // Spec: "Arrows" | "Increase and decrease the value by one value or one stop indicator"
  // spec: sliders-a888cf, sliders-6c23ec
  describe("Arrows: Increase and decrease the value by one value or one stop indicator", () => {
    it("ArrowRight increases the value by one step", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowRight');
      expect(valueOf(f)).toBe(51);
    });

    it("ArrowLeft decreases the value by one step", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowLeft');
      expect(valueOf(f)).toBe(49);
    });

    it("ArrowDown decreases the value by one step", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowDown');
      expect(valueOf(f)).toBe(49);
    });

    it("ArrowUp increases the value by one step", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowUp');
      expect(valueOf(f)).toBe(51);
    });
  });

  // Spec: "Space & Arrows" | "Increase and decrease the value by one interval or one stop indicator"
  // spec: sliders-e26fe9, sliders-ead175
  describe("Space & Arrows: Increase and decrease the value by one interval or one stop indicator", () => {
    it("Space+ArrowRight increases the value by one stop", async () => {
      const f = await setup({step: 10});
      await focusItem(f, 0);
      await hold(["Space"], 'ArrowRight');
      expect(valueOf(f)).toBe(60);
    });

    it("Space+ArrowLeft decreases the value by one stop", async () => {
      const f = await setup({step: 10});
      await focusItem(f, 0);
      await hold(["Space"], 'ArrowLeft');
      expect(valueOf(f)).toBe(40);
    });

    it("Space+ArrowDown decreases the value by one stop", async () => {
      const f = await setup({step: 10});
      await focusItem(f, 0);
      await hold(["Space"], 'ArrowDown');
      expect(valueOf(f)).toBe(40);
    });

    it("Space+ArrowUp increases the value by one stop", async () => {
      const f = await setup({step: 10});
      await focusItem(f, 0);
      await hold(["Space"], 'ArrowUp');
      expect(valueOf(f)).toBe(60);
    });
  });

  // Spec: "Home or End" | "Set the slider to the first and last values on the slider"
  // spec: sliders-89aa4e, sliders-85ad1d
  describe("Home or End: Set the slider to the first and last values on the slider", () => {
    it("Home sets the minimum value", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('Home');
      expect(valueOf(f)).toBe(0);
    });

    it("End sets the maximum value", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('End');
      expect(valueOf(f)).toBe(100);
    });
  });
});
